contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);
        address burner = address(this);
        uint256 balBefore = c.balanceOf(burner); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 distributedBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;
        require(amount <= balBefore);
        c.burn(amount); if (__ESBMC_reverted()) return;
        uint256 balAfter = c.balanceOf(burner); if (__ESBMC_reverted()) return;
        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 distributedAfter = c.totalDistributed(); if (__ESBMC_reverted()) return;
        assert(balAfter == balBefore - amount && supplyAfter == supplyBefore - amount && distributedAfter == distributedBefore - amount);
    }

    receive() external payable {}
}

