        c = new XBORNID();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        address burner = address(this);
        uint256 balBefore;
        try c.balanceOf(burner) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        uint256 distributedBefore;
        try c.totalDistributed() returns (uint256 __r) { distributedBefore = __r; } catch { return; }
        vm.assume(amount <= balBefore);
        try c.burn(amount) {} catch { return; }
        uint256 balAfter;
        try c.balanceOf(burner) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint256 supplyAfter;
        try c.totalSupply() returns (uint256 __r) { supplyAfter = __r; } catch { return; }
        uint256 distributedAfter;
        try c.totalDistributed() returns (uint256 __r) { distributedAfter = __r; } catch { return; }
        assertTrue(balAfter == balBefore - amount && supplyAfter == supplyBefore - amount && distributedAfter == distributedBefore - amount);
